import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'flutter_flow/flutter_flow_util.dart';

class FFAppState extends ChangeNotifier {
  static FFAppState _instance = FFAppState._internal();

  factory FFAppState() {
    return _instance;
  }

  FFAppState._internal();

  static void reset() {
    _instance = FFAppState._internal();
  }

  Future initializePersistedState() async {
    prefs = await SharedPreferences.getInstance();
    _safeInit(() {
      _isTicketOn = prefs.getBool('ff_isTicketOn') ?? _isTicketOn;
    });
    _safeInit(() {
      _ticketNumber = prefs.getString('ff_ticketNumber') ?? _ticketNumber;
    });
  }

  void update(VoidCallback callback) {
    callback();
    notifyListeners();
  }

  late SharedPreferences prefs;

  String _temp = '';
  String get temp => _temp;
  set temp(String value) {
    _temp = value;
  }

  bool _isTicketOn = false;
  bool get isTicketOn => _isTicketOn;
  set isTicketOn(bool value) {
    _isTicketOn = value;
    prefs.setBool('ff_isTicketOn', value);
  }

  String _ticketNumber = '';
  String get ticketNumber => _ticketNumber;
  set ticketNumber(String value) {
    _ticketNumber = value;
    prefs.setString('ff_ticketNumber', value);
  }

  String _defaultpic =
      '';
  String get defaultpic => _defaultpic;
  set defaultpic(String value) {
    _defaultpic = value;
  }
}

void _safeInit(Function() initializeField) {
  try {
    initializeField();
  } catch (_) {}
}

Future _safeInitAsync(Function() initializeField) async {
  try {
    await initializeField();
  } catch (_) {}
}
